def metrics_table(results, labels):
    rows=''
    for key,label in labels:
        r=results[key]
        rows+=f'<tr class="{"highlight" if key=="disagreement" else ""}"><td>{esc(label)}</td><td class="numeric">{r["dti"]:.6f}</td><td class="numeric">[{r["ci95"][0]:.6f}, {r["ci95"][1]:.6f}]</td></tr>'
    return '<div class="table-wrap"><table><thead><tr><th>Procedure</th><th>HOLDOUT-DTI</th><th>95% CI</th></tr></thead><tbody>'+rows+'</tbody></table></div>'


def make_preview(card):
    import numpy as np
    import rasterio
    from PIL import Image
    p=ROOT/'work/ctd5/features/valid.npy'
    if not p.exists(): return
    valid=np.load(p)
    scale=600/valid.shape[0];w=int(round(valid.shape[1]*scale));h=600
    mask=np.asarray(Image.fromarray(valid).resize((w,h),Image.Resampling.NEAREST))
    rgb=np.zeros((h,w,3),np.uint8);rgb[:]=(16,47,55);rgb[mask]=(34,70,76)
    with rasterio.open(ROOT/'submission'/card['raster_file']) as ds: a=ds.read(1)>0
    yy,xx=np.nonzero(a);y=np.minimum((yy*scale).astype(int),h-1);x=np.minimum((xx*scale).astype(int),w-1)
    rgb[y,x]=(98,202,165)
    with (EV/card['reasoning']['pixel_csv']).open() as f:
        for r in csv.DictReader(f):
            if r['A_only_candidate_id']:
                y=min(int(int(r['row'])*scale),h-1);x=min(int(int(r['col'])*scale),w-1)
                rgb[y,x]=(241,189,101)
    Image.fromarray(rgb).save(DOC/'assets/ctd5-prediction.png')


def source_claims():
    reference=json.loads((ROOT/'work/ctd5/sources/official-reference-tree.json').read_text()) if (ROOT/'work/ctd5/sources/official-reference-tree.json').exists() else {'sha':'aebe92f7c8a990f0e3443451b7a825d9afd6336b'}
    rows=[
      dict(claim='Official baseline offers CPU and GPU options; GPU is not mandatory for this boosting run.',status='Official GitHub source read this session',url='https://github.com/drivendataorg/gems-prize-reference-solution/blob/'+reference['sha']+'/README.md',evidence='Source blob a8814f99c395d12a8e1c3731c738e61d7dca06b5; actual CTD5 fits ran on CPU.'),
      dict(claim='The target is fault prediction; a raster does not establish a geothermal reservoir.',status='Prior dated official-source audit; not freshly fetched',url='https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/',evidence='evidence/verified_claims_r2.json C01/C02; official reference notebook describes fault detection.'),
      dict(claim='DTI uses the requested 300 m triangular kernel with alpha .2 and beta .8.',status='User specification + prior dated source audit + independently tested local arithmetic',url='https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/',evidence='evidence/verified_claims_r2.json C03; tests/test_metric.py and tests/test_ctd5.py.'),
      dict(claim='Known catalogue pixels are excluded pixel-exactly; off-catalogue flanks are not automatically exempt.',status='Prior dated organizer-staff statement, not a fresh portal retrieval',url='https://community.drivendata.org/t/scoring-clarification-are-known-usgs-ingenious-faults-masked-when-scoring-and-are-they-in-the-final-round-label-set/11516/4',evidence='evidence/verified_claims_r2.json C05/C06.'),
      dict(claim='Co-training assumptions are not established by weak proxy-negative error correlation.',status='Primary-paper link + prior dated literature review; empirical diagnostic measured here',url='https://doi.org/10.1145/279943.279962',evidence='Blum & Mitchell COLT 1998; CTD5 independence and transfer receipts.'),
      dict(claim='GeoDAWN is an official magnetic/radiometric data source; no fresh raw official-host download occurred here.',status='Official source identified; sandbox-host access restricted',url='https://www.usgs.gov/data/geodawn-airborne-magnetic-and-radiometric-surveys-northwestern-great-basin-nevada-and',evidence='DOI 10.5066/P93LGLVQ. Band-6 identity remains disputed; no external radiometric layer trained this run.'),
      dict(claim='Integrated structural/geophysical evidence can motivate blind-system investigations; it does not confirm these candidates.',status='Prior dated official-publication review; hypothesis support only',url='https://www.usgs.gov/publications/discovering-blind-geothermal-systems-great-basin-region-integrated-geologic-and',evidence='DOI 10.2172/1724080; no field validation in CTD5.'),
      dict(claim='INGENIOUS is an official free-data starting point, not independent proof of a proposed fault.',status='Official source identified; raw download and current terms not reverified here',url='https://gdr.openei.org/submissions/1391',evidence='DOI 10.15121/1881483. No external chemistry, fault or vent features used in CTD5.'),
      dict(claim='Competition rules and current allowance must be checked before an independently approved upload.',status='Rules link retained; current submission-page cap/receipt unavailable',url='https://docs.nlr.gov/docs/fy26osti/96647.pdf',evidence='No submission-page receipt, no upload, no slot consumed. Generative-AI assistance disclosed in the research narrative.'),
      dict(claim='Core input files match the manifest pins, not authenticated organizer downloads.',status='Locally verified bytes; organizer provenance unresolved',url=REPO+'/blob/main/registry/data_manifest.json',evidence='evidence/ctd5_input_integrity.json; 23 mirrored inputs restored and SHA-checked.'),
    ]
    (EV/'ctd5_claims.json').write_text(json.dumps(dict(checked_date_utc='2026-10-08',claims=rows),indent=2)+'\n')
    # Preserve the owner/user result list without joining it to a fabricated receipt.
    text=(ROOT/'knowledge/26_current_user_brief.md').read_text().split('The following is the leaderboard for the competition:')[0]
    site=None; seen=set(); reports=[]
    for line in text.splitlines():
        match=re.search(r'https://buffedlizard55-lab.github.io/([^/]+)/',line)
        if match: site=match.group(1)
        m=re.fullmatch(r'([\w.-]+):\s*(0\.\d+)?',line.strip())
        if m and site and (site,m.group(1)) not in seen:
            seen.add((site,m.group(1)))
            reports.append(dict(site=site,submission_label=m.group(1),reported_value=float(m.group(2)) if m.group(2) else None,
                evidence_class='OWNER/USER-REPORTED; NOT ORGANIZER-CONFIRMED',receipt=None,authenticated_file_sha256=None))
    (EV/'ctd5_owner_reported_results.json').write_text(json.dumps(dict(source='knowledge/26_current_user_brief.md',entries=reports,
        warning='Reported associations are not verified scores and are never model inputs or promotion evidence.'),indent=2)+'\n')
    return rows,reports


